func TestServeRunFailureInterruptsOpen(t *testing.T) {
	runErr := errors.New("run failed")
	openErr := errors.New("open interrupted")
	jobs := make(chan Job, 2)
	jobs <- 1
	jobs <- 2
	close(jobs)
	openStarted := make(chan struct{})
	var closed atomic.Int64
	ctx, cancel := context.WithCancel(context.Background())
	finished := make(chan error, 1)
	done := make(chan struct{})
	go func() {
		defer close(done)
		finished <- Serve(ctx, jobs, 2, func(openCtx context.Context, job Job) (Lease, error) {
			if job == 2 {
				close(openStarted)
				<-openCtx.Done()
				return nil, openErr
			}
			return leaseFuncs{
				run: func(context.Context, Job) error {
					<-openStarted
					return runErr
				},
				close: func() error {
					closed.Add(1)
					return nil
				},
			}, nil
		})
	})
	t.Cleanup(func() {
		cancel()
		await(t, done)
	})
	err := await(t, finished)
	if !errors.Is(err, runErr) || !errors.Is(err, openErr) || closed.Load() != 1 {
		t.Fatalf("Serve=%v closed=%d, want both errors and one close", err, closed.Load())
	}
}

func TestServeIndependentRunAndCloseFailures(t *testing.T) {
	runErr := errors.New("run failed")
	closeErr := errors.New("close failed")
	for _, tc := range []struct {
		name     string
		runErr   error
		closeErr error
	}{
		{"run only", runErr, nil},
		{"close only", nil, closeErr},
		{"both", runErr, closeErr},
	} {
		t.Run(tc.name, func(t *testing.T) {
			jobs := make(chan Job, 1)
			jobs <- 1
			close(jobs)
			closes := 0
			err := Serve(context.Background(), jobs, 2, func(context.Context, Job) (Lease, error) {
				return leaseFuncs{
					run:   func(context.Context, Job) error { return tc.runErr },
					close: func() error { closes++; return tc.closeErr },
				}, nil
			})
			for _, want := range []error{tc.runErr, tc.closeErr} {
				if want != nil && !errors.Is(err, want) {
					t.Fatalf("Serve = %v, missing %v", err, want)
				}
			}
			if closes != 1 {
				t.Fatalf("closes = %d, want 1", closes)
			}
		})
	}
}

package workers

import (
	"context"
	"errors"
)

// Job identifies a requested operation.
type Job int

// Lease supplies the existing cooperative operation and release boundary.
type Lease interface {
	Run(context.Context, Job) error
	Close() error
}

// Serve runs supplied jobs using leases acquired by the host.
func Serve(ctx context.Context, jobs <-chan Job, limit int, open func(context.Context, Job) (Lease, error)) error {
	runCtx, stop := context.WithCancel(ctx)
	defer stop()

	var failures []error
	inputClosed := false
	for {
		// Acquired leases occupy capacity until the entire cohort has finished
		// running and every lease has been closed.
		leases := make([]Lease, 0, limit)
		finished := make(chan error, limit)
		running := 0
		stopping := false

		for len(leases) < limit && !inputClosed && !stopping {
			select {
			case <-runCtx.Done():
				stopping = true
			case err := <-finished:
				running--
				if err != nil {
					failures = append(failures, err)
					stopping = true
				}
			case job, ok := <-jobs:
				if !ok {
					inputClosed = true
					break
				}
				if runCtx.Err() != nil {
					stopping = true
					break
				}
				lease, err := open(runCtx, job)
				if err != nil {
					failures = append(failures, err)
					stopping = true
					stop()
					break
				}
				leases = append(leases, lease)
				if runCtx.Err() != nil {
					stopping = true
					break
				}
				running++
				go func() {
					err := lease.Run(runCtx, job)
					if err != nil {
						stop()
					}
					finished <- err
				}()
			}
		}

		// A failure in one Run requests a stop immediately, including while
		// admission is blocked in a cooperative Open.
		for running > 0 {
			err := <-finished
			running--
			if err != nil {
				failures = append(failures, err)
				stopping = true
			}
		}
		for _, lease := range leases {
			if err := lease.Close(); err != nil {
				failures = append(failures, err)
				stopping = true
				stop()
			}
		}
		if stopping || inputClosed || runCtx.Err() != nil {
			break
		}
	}
	if ctx.Err() != nil {
		failures = append(failures, ctx.Err())
	}
	return errors.Join(failures...)
}

